function renderHistory() {
  const term = document.getElementById("history-search").value.trim().toLocaleLowerCase("tr-TR");
  const items = state.historyItems.filter(h => {
    const inCategory = state.activeHistoryCat === "Tümü" || h.cat === state.activeHistoryCat;
    const searchable = [h.cat, h.period, h.title, h.summary, h.places, ...h.concepts].join(" ").toLocaleLowerCase("tr-TR");
    return inCategory && (!term || searchable.includes(term));
  });
  document.getElementById("history-count").textContent = `${items.length} / ${state.historyItems.length} kayıt · Tarih Öncesi → 2026`;
  document.getElementById("history-list").innerHTML = items.length ? items.map(h => `<article class="item history-item"><div><span class="tag hist">${h.cat}</span><span class="meta">${h.period}</span></div><div style="font-weight:700; margin-top:6px;">${h.title}</div><p style="margin-top:4px; font-size:0.86rem; color:#cbd5e1;">${h.summary}</p><div class="history-facts"><span><b>📍 Mekânlar:</b> ${h.places}</span></div><div class="history-concepts" aria-label="Anahtar kavramlar">${h.concepts.map(c => `<span class="concept">${c}</span>`).join("")}</div></article>`).join("") : `<div class="empty-state">Bu aramada kayıt bulunamadı. Başka bir dönem, mekân veya kavram deneyin.</div>`;
}
document.getElementById("history-search").addEventListener("input", renderHistory);

